import json
from pathlib import Path

session_dir = Path("/home/USER/runs/paper/qwen-h0c1-card/frozen/seen-reference-3/play/users/u086/system/state/session-artifacts/01a188fc-f815-73da-bebe-c79d5be6d64e")

# Search for any demo with background=5 in grids.json
grids_path = session_dir / "grids.json"
with open(grids_path) as f:
    data = json.load(f)

for key, val in data.items():
    print(f"\n=== {key} ===")
    if isinstance(val, dict) and 'input' in val:
        inp = val['input']
        if len(inp) > 0:
            bg_counts = {}
            for row in inp:
                for v in row:
                    bg_counts[v] = bg_counts.get(v, 0) + 1
            bg_val = max(bg_counts.items(), key=lambda x: x[1])[0]
            print(f"Background: {bg_val}")

            # Count how many of each non-bg value exist
            all_vals = set()
            for row in inp:
                all_vals.update(row)
            for v in sorted(all_vals):
                if v != bg_val:
                    count = sum(r.count(v) for r in inp)
                    print(f"  Value {v}: {count} occurrences")

print("\n\nLooking for demos with different backgrounds...")

